+  const end = argv.indexOf('--');
+  const flags = argv.slice(1, end === -1 ? undefined : end).filter((w) => w.startsWith('-'));
+  const recursive = flags.some((w) => w === '--recursive' || shortHas(w, 'rR'));
+  if (!recursive) return undefined;
