+
+  const lineOf = (pos: number) => content.slice(0, pos).split('\n').length;
+
+  // 1. exact
+  const hits: number[] = [];
+  for (let i = content.indexOf(old_text); i !== -1; i = content.indexOf(old_text, i + old_text.length)) hits.push(i);
+  if (hits.length > 1 && !replace_all) {
+    return { error: `old_text matches ${hits.length} places, first at line ${lineOf(hits[0])}` };
+  }
+  if (hits.length > 0) {
+    const replaced = replace_all ? content.split(old_text).join(new_text) : content.slice(0, hits[0]) + new_text + content.slice(hits[0] + old_text.length);
+    const from = lineOf(hits[0]);
