+  const newLines = new_text === '' ? [] : stripNl(new_text).split('\n');
+  const lines = content.split('\n');
+  const n = oldLines.length;
+  const windowsWhere = (same: (a: string, b: string) => boolean) => {
+    const starts: number[] = [];
+    for (let i = 0; i + n <= lines.length; i++) {
+      if (oldLines.every((l, k) => same(lines[i + k], l))) starts.push(i);
+    }
+    return starts;
+  };
+  const ambiguous = (starts: number[]) =>
+    `old_text matches ${starts.length} places at lines ${starts.map((i) => i + 1).join(', ')}`;
+
+  // 2. trailing-space
+  const trimEndStarts = windowsWhere((a, b) => a.trimEnd() === b.trimEnd());
+  if (trimEndStarts.length > 1) return { error: ambiguous(trimEndStarts) };
+  if (trimEndStarts.length === 1) {
+    const i = trimEndStarts[0];
+    const out = [...lines.slice(0, i), ...newLines, ...lines.slice(i + n)];
+    return { content: out.join('\n'), applied: { from: i + 1, to: i + n, tier: 'trailing-space', count: 1 } };
+  }
