+// Shortcuts that make work look done. Found in the run's own changes only, never in files it did not touch.
+// A finding is a flag: it is reminded once and recorded, never a refusal.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type SlopFinding = { rule: string; path: string; line?: string };
+
+const CODE = /\.(ts|tsx|js|jsx|mjs|cjs|py|go|rs|java|kt|rb|php|cs|swift|c|cc|cpp|h|hpp|sh)$/;
+const TEST = /(\.test\.|\.spec\.|_test\.|(^|\/)test_[^/]*$|(^|\/)tests?\/|(^|\/)__tests__\/)/;
+const SKIP = /\b(it|test|describe|suite)\.(skip|todo)\(|\bx(it|describe|test)\(|\bt\.Skip(Now)?\(|@(pytest\.mark\.)?skip\b|\bpytest\.skip\(/;
+const ASSERT = /\b(expect|assert\w*)\b/g;
+const LINE_RULES: [string, RegExp][] = [
+  ['suppression', /@ts-(ignore|expect-error|nocheck)\b|\beslint-disable|#\s*type:\s*ignore|#\s*noqa\b|#\s*pylint:\s*disable|\/\/\s*nolint/],
+  ['swallowed-error', /catch\s*(\([^)]*\))?\s*\{\s*\}|^\s*except\b.*:\s*pass\s*$/],
+  ['type-escape', /\bas any\b|<any>|:\s*any\b/],
+  ['stub', /not implemented|NotImplementedError|unimplemented!|todo!\(\)/i],
+];
+
+export function findSlop(changes: FileChange[]): SlopFinding[] {
+  const out: SlopFinding[] = [];
+  for (const c of changes) {
+    if (TEST.test(c.path)) {
+      if (c.deleted) out.push({ rule: 'test-deleted', path: c.path });
+      else {
+        const count = (ls: string[]) => ls.reduce((n, l) => n + (l.match(ASSERT)?.length ?? 0), 0);
+        if (count(c.added) < count(c.removed)) out.push({ rule: 'test-weakened', path: c.path });
+        for (const l of c.added) if (SKIP.test(l)) out.push({ rule: 'test-skipped', path: c.path });
+      }
+    }
+    if (c.deleted || !CODE.test(c.path)) continue;
+    for (const l of c.added) {
+      const hit = LINE_RULES.find(([, re]) => re.test(l));
+      if (hit) out.push({ rule: hit[0], path: c.path, line: l.trim().slice(0, 160) });
+    }
+  }
