+// Shortcuts that make work look done. Pure: it reads a run's changes, never the model.
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type SlopFinding = { rule: string; path: string; text?: string };
+
+const CODE = /\.(c|cc|cpp|go|h|java|js|jsx|mjs|cjs|kt|py|rb|rs|swift|ts|tsx)$/;
+const TEST_FILE = /(^|\/)(tests?|__tests__)\/|(\.test|\.spec|_test)\.\w+$|(^|\/)test_[^/]*$/;
+const ASSERT = /\bassert|\bexpect\(|\.should\b|\bt\.(Errorf?|Fatalf?)\(/;
+const SKIP = /\b(test|it|describe)\.skip\(|\bx(it|describe|test)\(|\bt\.Skip\(|@pytest\.mark\.skip|pytest\.skip\(|@Disabled\b/;
+const SUPPRESS = /@ts-(ignore|nocheck)\b|eslint-disable|#\s*type:\s*ignore|#\s*noqa\b|#\s*pylint:\s*disable|\/\/\s*nolint\b/;
+const SWALLOW = /catch\s*(\([^)]*\))?\s*\{\s*\}|^\s*except\b.*:\s*pass\s*$/;
+const TYPE_ESCAPE = /\bas any\b/;
+const STUB = /throw new Error\(['"`]not implemented['"`]\)|NotImplementedError|\btodo!\(\)|\bunimplemented!\(\)/i;
+
+const LINE_RULES: [string, RegExp][] = [
+  ['suppression', SUPPRESS],
+  ['swallowed-error', SWALLOW],
+  ['type-escape', TYPE_ESCAPE],
+  ['stub', STUB],
+];
+
+export function findSlop(changes: FileChange[]): SlopFinding[] {
+  const out: SlopFinding[] = [];
+  for (const c of changes) {
+    const isTest = TEST_FILE.test(c.path);
+    if (isTest && c.deleted) out.push({ rule: 'test-deleted', path: c.path });
+    if (isTest && !c.deleted) {
+      const asserts = (ls: string[]) => ls.filter((l) => ASSERT.test(l)).length;
+      if (asserts(c.removed) > asserts(c.added)) out.push({ rule: 'test-weakened', path: c.path });
+      for (const l of c.added) if (SKIP.test(l)) out.push({ rule: 'test-skipped', path: c.path, text: l.trim() });
+    }
+    if (!CODE.test(c.path)) continue;
+    for (const l of c.added)
+      for (const [rule, re] of LINE_RULES) if (re.test(l)) out.push({ rule, path: c.path, text: l.trim() });
+  }
+  return out;
+}
+
+// Reads a `git diff -U0` patch into per-file added and removed lines.
+export function changesFromPatch(patch: string): FileChange[] {
+  const out: FileChange[] = [];
+  let cur: FileChange | undefined;
+  let inHunk = false;
+  for (const line of patch.split('\n')) {
+    const head = /^diff --git a\/(.*) b\/(.*)$/.exec(line);
+    if (head) {
+      cur = { path: head[2]!, added: [], removed: [], deleted: false };
+      out.push(cur);
+      inHunk = false;
+      continue;
+    }
+    if (!cur) continue;
+    if (line.startsWith('deleted file mode')) cur.deleted = true;
+    else if (line.startsWith('@@')) inHunk = true;
+    else if (inHunk && line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (inHunk && line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
+  return out;
+}
+
+// What a finding says in the reminder, the receipt and the evidence flags.
+export const slopFlag = (f: SlopFinding) => (f.text ? `${f.rule} ${f.path}: ${f.text}` : `${f.rule} ${f.path}`);
