+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+
+// Expected values worked by hand from the rules in README.md.
+describe('pricing rules', () => {
+  test('bulk discount applies at exactly 10 units', () => {
+    // 10 mugs = 4500; 5% = 225
+    expect(totals(cart('US', [['MUG', 10]])).lines[0]).toMatchObject({ subtotal: 4500, discount: 225 });
+  });
+
+  test('bulk discount applies at exactly 50 units, 10% off', () => {
+    // 50 mugs = 22500; 10% = 2250; 20250 >= 5000 so no shipping; tax 7% of 20250 = 1417.5 -> 1418
+    expect(totals(cart('US', [['MUG', 50]]))).toMatchObject({ subtotal: 20250, shipping: 0, tax: 1418, total: 21668 });
+  });
+
+  test('quantities of the same sku are merged before bulk pricing', () => {
+    // 5 + 5 mugs = 10 units -> 5% off the 4500 line
+    expect(totals(cart('US', [['MUG', 5], ['MUG', 5]])).subtotal).toBe(4275);
+  });
+
+  test('free shipping is decided on the discounted subtotal', () => {
+    // 12 mugs = 5400; 5% = 270 -> 5130; SAVE10 = 513 -> 4617 < 5000, so shipping 800
+    // tax 7% of 5417 = 379.19 -> 379; total 4617 + 800 + 379
+    expect(totals(cart('US', [['MUG', 12]], 'SAVE10'))).toMatchObject({ subtotal: 5130, coupon: 513, shipping: 800, tax: 379, total: 5796 });
+  });
+
+  test('UK free shipping starts at 4000', () => {
+    // 2 bags = 4400 >= 4000; tax 20% of 4400 = 880
+    expect(totals(cart('UK', [['BAG', 2]]))).toMatchObject({ shipping: 0, tax: 880, total: 5280 });
+  });
+});

