+import { region } from '../src/pricing/regions.ts';
+
+describe('bulk discount tiers', () => {
+  test('10 units get 5% and 50 units get 10%', () => {
+    expect(bulkDiscount(9, 4050)).toBe(0);
+    expect(bulkDiscount(10, 1200)).toBe(60);
+    expect(bulkDiscount(49, 22050)).toBe(1103);
+    expect(bulkDiscount(50, 22500)).toBe(2250);
